// Ordered turn-by-turn instructions generated by the backend from the route graph, each with the step-free status
// of its pathway as returned (verified, reported or unknown).
import type { RouteResult, StepFree } from '../../../api/types'
import { useApp } from '../../PlannerContext'

const TONE: Record<StepFree, string> = {
  verified: 'bg-match-50 text-match-700',
  reported: 'bg-amber-50 text-amber-800',
  unknown: 'bg-ink-100 text-ink-700',
}

interface Props {
  route: RouteResult | null
  activeStep: number | null
  emptyText: string
}

export function StepList({ route, activeStep, emptyText }: Props) {
  const { m } = useApp()
  const n = m.navigation
  const instructions = route?.status === 'ok' ? route.instructions : []
  if (instructions.length === 0) {
    return <p className="rounded-2xl bg-ink-100 p-4 text-center text-sm text-ink-500">{emptyText}</p>
  }
  const byEdge = new Map(route!.segments.map((s) => [s.edge_id, s]))
  return (
    <ol className="space-y-2" aria-label={n.steps}>
      {instructions.map((ins, i) => {
        const active = activeStep === i
        const done = activeStep !== null && i < activeStep
        const seg = ins.edge_id ? byEdge.get(ins.edge_id) : undefined
        return (
          <li key={ins.step} aria-current={active ? 'step' : undefined}
            className={`flex gap-3 rounded-xl p-3 text-sm shadow-card ring-1 ${active ? 'bg-brand-50 ring-brand-500' : 'bg-white ring-ink-100'} ${done ? 'opacity-60' : ''}`}>
            <span className={`grid h-7 w-7 shrink-0 place-items-center rounded-full text-xs font-bold ${active || done ? 'bg-brand-600 text-white' : 'bg-brand-50 text-brand-700'}`}>
              {done ? '✓' : ins.step}
            </span>
            <span className="min-w-0 flex-1">
              <span className="block text-ink-900">{ins.text}</span>
              {ins.distance_m != null && (
                <span className="block text-xs text-ink-500">{ins.distance_is_estimate ? `${n.approx} ` : ''}{Math.round(ins.distance_m)} m</span>
              )}
              {seg && (
                <span data-step-free={seg.step_free} className={`mt-1 inline-block rounded-full px-2 py-0.5 text-[11px] font-semibold ${TONE[seg.step_free]}`}>
                  {n.stepFree[seg.step_free]}
                </span>
              )}
            </span>
          </li>
        )
      })}
    </ol>
  )
}
